from __future__ import annotations

import warnings

import numpy as np
import QuantLib as ql

from .base import Model, PathSampler


class HestonModel(Model):
    """Heston model whose paths are generated by QuantLib.

    ``s0_handle`` is the spot quote, ``riskFreeTS`` and ``dividendTS`` the
    rate and dividend-yield curves. ``v0`` is the initial variance, ``theta``
    the long-run variance, ``kappa`` the mean-reversion speed, ``sigma`` the
    volatility of variance and ``rho`` the correlation between the spot and
    variance Brownian motions.

    Paths come from ``ql.GaussianMultiPathGenerator`` on a ``ql.HestonProcess``
    with QuantLib's default ``QuadraticExponentialMartingale`` discretisation.
    The path loop runs in Python, so this sampler is much slower than
    :class:`~option_pricer.models.NumbaHestonSampler` and does not support
    common random numbers or antithetic variates; it is mainly an independent
    cross-check.
    """

    supports_crn = False
    supports_antithetic = False

    def __init__(
        self,
        s0_handle: ql.QuoteHandle,
        riskFreeTS: ql.YieldTermStructureHandle,
        dividendTS: ql.YieldTermStructureHandle,
        v0: float,
        kappa: float,
        theta: float,
        sigma: float,
        rho: float,
    ) -> None:
        self.v0 = float(v0)
        self.kappa = float(kappa)
        self.theta = float(theta)
        self.sigma = float(sigma)
        self.rho = float(rho)

        if not -1.0 <= self.rho <= 1.0:
            raise ValueError("rho must lie in [-1, 1]")
        if self.v0 < 0.0 or self.theta < 0.0 or self.sigma < 0.0 or self.kappa <= 0.0:
            raise ValueError("v0, theta and sigma must be non-negative and kappa positive")
        if 2.0 * self.kappa * self.theta < self.sigma * self.sigma:
            warnings.warn(
                "Feller condition 2*kappa*theta >= sigma^2 is violated: "
                "the variance process can reach zero",
                stacklevel=2,
            )

        self._s0 = s0_handle
        self._r = riskFreeTS
        self._q = dividendTS

        self._process = ql.HestonProcess(
            self._r, self._q, self._s0, self.v0, self.kappa, self.theta, self.sigma, self.rho
        )
        self._ql_model = ql.HestonModel(self._process)

    def s0(self) -> float:
        return float(self._s0.value())

    def discount(self, t: float) -> float:
        return float(self._r.discount(float(t)))

    def path_sampler(self) -> PathSampler:
        process = self._process

        def sampler(
            n_paths: int,
            timegrid: np.ndarray,
            randnumbergenerator: np.random.Generator,
            randnumber_key: str | None = None,
            z: np.ndarray | None = None,
        ) -> np.ndarray:
            # QuantLib's Mersenne Twister takes a 32-bit seed drawn from the engine RNG.
            seed = int(randnumbergenerator.integers(2**31 - 1))
            t_grid = ql.TimeGrid(list(map(float, timegrid)))
            n_steps = len(t_grid) - 1
            dim = process.factors() * n_steps

            ursg = ql.UniformRandomSequenceGenerator(dim, ql.UniformRandomGenerator(seed))
            grsg = ql.GaussianRandomSequenceGenerator(ursg)
            pg = ql.GaussianMultiPathGenerator(process, t_grid, grsg, False)

            s = np.empty((n_paths, len(t_grid)))
            for i in range(n_paths):
                spot_path = pg.next().value()[0]
                for j in range(len(t_grid)):
                    s[i, j] = spot_path[j]
            return s

        return sampler
